 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Detect downward-pointing triangular outlines from a top apex and fill
    # cells strictly between both colored diagonal arms. Ignore partial V's
    # that lack a visible arm on one side.
    for c in range(w):
        if grid[0][c] == 0:
            continue
        for r in range(1, h):
            left, right = c-r, c+r
            if left < 0 or right >= w:
                break
            if grid[r][left] == 0 or grid[r][right] == 0:
                continue
            for x in range(left+1, right):
                if grid[r][x] == 0:
                    out[r][x] = 2
    return out
